/*
Program Name: SASZombieAssaultTD
File Path: Engine/UI/HUDPanel_Main.cs
Purpose: Main HUD panel renderer implementing IHUDElement interface for main panel display.
Features:
  - Implements IHUDElement interface for HUD element integration
  - Currently in placement mode for visual positioning and alignment
  - Draws white rectangle with placeholder text for spatial reference
  - Final colors and content applied through HUDPanel_Main_Finalizer
  - Part of global HUD color pipeline receiving colors from Finalizer
  - No baked-in defaults, flash colors, or fallback logic applied
  - Provides panel geometry properties: X, Y, Width, Height
  - Uses deterministic fields for visual placement
*/

using SASZombieAssaultTD.Engine.Rendering;using SASZombieAssaultTD.Engine.Diagnostics;  using SASZombieAssaultTD.Engine.Rendering; using System.Numerics;  // Resolve IRenderContext ambiguity using IRenderContext = SASZombieAssaultTD.Engine.Rendering.IRenderContext;  namespace SASZombieAssaultTD.Engine.UI {     /// <summary>     /// Main HUD panel renderer implementing IHUDElement interface.     /// Currently in placement mode for visual positioning and alignment.     /// Draws a white rectangle with placeholder text for spatial reference.     /// Final colors and content will be applied through HUDPanel_Main_Finalizer.     /// Part of the global HUD color pipeline receiving colors from Finalizer.     /// No baked-in defaults, flash colors, or fallback logic are applied.     /// </summary>     public class HUDPanel_Main : IHUDElement     {         /// <summary>         /// Unique identifier for this HUD panel element.         /// Used by HUDManager for element tracking and render order management.         /// Matches the panel identifier used in HUDPanel_Main_Finalizer configuration.         /// </summary>         public string Id => "main_panel";          // ---------------------------------------------------------         // PANEL GEOMETRY (DETERMINISTIC FIELDS FOR VISUAL PLACEMENT)         // ---------------------------------------------------------          /// <summary>         /// Horizontal position of the main panel in screen coordinates.         /// Current value is a placeholder for visual tuning (5 pixels from left).         /// Final position will be determined through visual alignment with HUD art.         /// Values are persisted to configuration when placement is finalized.         /// </summary>         public int X { get; set; } = 5;          /// <summary>         /// Vertical position of the main panel in screen coordinates.         /// Current value is a placeholder for visual tuning (500 pixels from top).         /// Final position will be determined through visual alignment with HUD art.         /// Values are persisted to configuration when placement is finalized.         /// </summary>         public int Y { get; set; } = 500;          /// <summary>         /// Width of the main panel background in pixels.         /// Current value (120px) is a placeholder for visual sizing.         /// Final size will be determined through visual alignment requirements.         /// Values are persisted to configuration when placement is finalized.         /// </summary>         public int Width { get; set; } = 120;          /// <summary>         /// Height of the main panel background in pixels.         /// Current value (20px) is a placeholder for visual sizing.         /// Final size will be determined through visual alignment requirements.         /// Values are persisted to configuration when placement is finalized.         /// </summary>         public int Height { get; set; } = 20;          // ---------------------------------------------------------         // PLACEHOLDER CONTENT (WILL BE REPLACED WITH REAL DATA)         // ---------------------------------------------------------          /// <summary>         /// Placeholder text displayed in the main panel during placement mode.         /// Current value "MAIN" is for visual reference only.         /// Will be replaced with actual game content when panel is finalized.         /// Updated by HUDPanel_Main_Finalizer during color distribution.         /// </summary>         private string _displayText = "MAIN";          // ---------------------------------------------------------         // DEBUG RENDERING (VISUAL PLACEMENT AID)         // ---------------------------------------------------------          /// <summary>         /// Debug renderer that draws a white rectangle for visual positioning.         /// Provides clear visual reference for panel alignment during placement.         /// Used to tune X, Y, Width, and Height values against HUD artwork.         /// Will be removed or disabled when panel placement is finalized.         /// </summary>         private DebugHUDRenderer _debug;          private string label;         private VectorMath.Vector3 pos;         private Color textColor;          /// <summary>         /// Rendering layer priority for this HUD element.         /// Set to 999 (higher than most elements) to ensure visibility during placement.         /// Draws above HUD artwork for clear positioning reference.         /// Will be adjusted to appropriate z-order when placement is finalized.         /// </summary>         public int Layer => 999;          // ---------------------------------------------------------         // UPDATE METHOD (IHUDElement IMPLEMENTATION)         // ---------------------------------------------------------          /// <summary>         /// Required IHUDElement Update method.         /// Main panel has no runtime update logic during placement mode.         /// All rendering state is determined during Draw call.         /// Called once per frame by HUDManager before Draw.         /// Will be expanded with runtime logic when panel is finalized.         /// </summary>         /// <param name="deltaTime">Time elapsed since last frame in seconds</param>         public void Update(float deltaTime)         {             // No logic yet — this panel is in placement mode only.             // Runtime updates will be added when panel receives real game data.         }          // ---------------------------------------------------------         // DRAW METHOD (IHUDElement IMPLEMENTATION)         // ---------------------------------------------------------          /// <summary>         /// Renders the main panel placement visualization.         /// Required IHUDElement Draw method called once per frame.         /// Draws white rectangle border for visual positioning reference.         /// Renders centered placeholder text for content area visualization.         /// Used to tune panel geometry against HUD artwork during development.         /// Will be replaced with actual content rendering when panel is finalized.         /// </summary>         /// <param name="context">Render context provided by HUD system</param>         public void Draw(IRenderContext context)         {             if (context is not Framebuffer fb)                 return;              if (_debug == null)                 _debug = new DebugHUDRenderer(context);              // Draw placement rectangle (white)             _debug.DrawWhiteRectangle(X, Y, Width, Height, 2);              // Draw placeholder text centered inside the rectangle             DrawCenteredText(context, _displayText, X, Y, Width, Height);         }          // ---------------------------------------------------------         // TEXT RENDERING HELPER (PLACEMENT VISUALIZATION)         // ---------------------------------------------------------          /// <summary>         /// Draws centered text within a rectangular region.         /// Helper method for placement mode visualization.         /// Calculates text position to center within specified bounds.         /// Uses fixed 14pt font size and white color for visibility.         /// Simple centering calculation assumes 8px average character width.         /// </summary>         /// <param name="context">Render context for text drawing</param>         /// <param name="text">Text string to display</param>         /// <param name="x">Left edge of containing rectangle</param>         /// <param name="y">Top edge of containing rectangle</param>         /// <param name="w">Width of containing rectangle</param>         /// <param name="h">Height of containing rectangle</param>         /// <summary>         /// Draws text centered within a rectangular area.         /// </summary>         /// <param name="x">Left edge of containing rectangle</param>         /// <param name="y">Top edge of containing rectangle</param>         /// <param name="w">Width of containing rectangle</param>         /// <param name="h">Height of containing rectangle</param>         private void DrawCenteredText(IRenderContext context, string text, int x, int y, int w, int h)         {             float textX = x + (w / 2f) - (text.Length * 4f);             float textY = y + (h / 2f) - 6f;              context.DrawText(                 text,                 new Vector3(textX, textY, 0),                 textColor.R,                 textColor.G,                 textColor.B,                 textColor.A,                 12f             );         }     } }
